export const KEY='mainichi-dinner-v1';
export function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function addDay(key,n){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d);}
export function monday(key){const d=new Date(key+'T12:00:00');return addDay(key,-((d.getDay()+6)%7));}
export function initialState(){return {version:1,plans:{},checks:{},history:{},family:['自分','娘','孫'].map((name,i)=>({id:String(i),name,ng:[],dislike:[]})),excluded:{}};}
export function matches(menu,tag){return menu.tags.some(t=>t.includes(tag)||tag.includes(t))||menu.ingredients.some(i=>i.name.includes(tag));}
export function ensurePlan(s,date,menus){if(s.plans[date])return s.plans[date];const banned=s.excluded[monday(date)]||[];let pool=menus.filter(m=>!banned.includes(m.id)&&!s.family.some(f=>f.ng.some(t=>matches(m,t))));if(!pool.length){return s.plans[date]={status:'empty'};}const recent=Object.entries(s.history).filter(([d])=>d<date&&d>=addDay(date,-7)).map(([,h])=>h.menuId);const preferred=pool.filter(m=>!recent.includes(m.id)&&!s.family.some(f=>f.dislike.some(t=>matches(m,t))));if(preferred.length)pool=preferred;const day=Math.round((new Date(date+'T12:00:00')-new Date('2026-09-10T12:00:00'))/86400000);return s.plans[date]={status:'planned',menuId:pool[((day%pool.length)+pool.length)%pool.length] .id};}
export function skipDay(s,date,reason,action,menus){if(!['tomorrow','skip'].includes(action))throw Error('献立の扱いを選んでください。');if(!['','外食','惣菜・弁当','家にある物で済ませる','予定あり','その他'].includes(reason))throw Error('理由を選び直してください。');const current=ensurePlan(s,date,menus);if(current.status!=='planned'||s.history[date])throw Error('食事済み、またはお休みの日は変更できません。');if(action==='tomorrow'){for(let i=1;i<=7;i++)ensurePlan(s,addDay(date,i),menus);const slots=[];for(let i=1;i<=366;i++){const d=addDay(date,i);if(!s.history[d]&&s.plans[d]?.status!=='skipped'){slots.push(d);if(!s.plans[d])break;}}if(!slots.length||s.plans[slots.at(-1)])throw Error('移動できる日がありません。');let carry={...current};for(const d of slots){const next=s.plans[d];s.plans[d]=carry;delete s.checks[d];carry=next;}}else{const week=monday(date);s.excluded[week]=[...new Set([...(s.excluded[week]||[]),current.menuId])];for(let i=0;i<7;i++){const d=addDay(week,i);if(d!==date&&s.plans[d]?.status==='planned'&&s.plans[d]?.menuId===current.menuId&&!s.history[d]){delete s.plans[d];delete s.checks[d];ensurePlan(s,d,menus);}}}s.plans[date]={status:'skipped',reason,action,originalMenuId:current.menuId};delete s.checks[date];return s.plans[date];}
export function eat(s,date,rating=null){const p=s.plans[date];if(p?.status!=='planned')throw Error('この日は食事を記録できません。');if(date>dateKey())throw Error('未来の日の食事は記録できません。');if(![null,'like','neutral','dislike'].includes(rating))throw Error('評価が不正です。');s.history[date]={menuId:p.menuId,rating,by:'family'};}
export function lastEaten(s,id){return Object.keys(s.history).filter(d=>s.history[d].menuId===id).sort().at(-1);}
export function favoriteIds(s){const latest={};Object.keys(s.history).sort().forEach(d=>{const h=s.history[d];if(h.rating!==null)latest[h.menuId]=h.rating;});return Object.keys(latest).filter(id=>latest[id]==='like');}
